// 每次打开固定一个相册快照，翻页不会串到其他房间或客厅。
export function setupPhotoViewer(){
 const dialog=document.createElement('dialog');dialog.className='photo-viewer';dialog.setAttribute('aria-labelledby','photo-viewer-title');
 dialog.innerHTML=`<div class="photo-viewer-header"><div><small>小家相册</small><h2 id="photo-viewer-title"></h2></div><button type="button" class="photo-viewer-close" aria-label="关闭照片">×</button></div><div class="photo-viewer-stage"><button type="button" class="photo-viewer-prev" aria-label="上一张照片">‹</button><div class="photo-viewer-image"><img alt="" draggable="false"><p class="photo-viewer-error" role="status" hidden>照片暂时无法加载，请关闭后重试。</p></div><button type="button" class="photo-viewer-next" aria-label="下一张照片">›</button></div><div class="photo-viewer-footer"><p class="photo-viewer-caption"></p><span class="photo-viewer-count" aria-live="polite"></span></div><p class="photo-viewer-hint">左右滑动或按 ← → 切换 · Esc 关闭</p>`;
 document.body.append(dialog);const q=s=>dialog.querySelector(s),image=q('img'),stage=q('.photo-viewer-image'),error=q('.photo-viewer-error'),prev=q('.photo-viewer-prev'),next=q('.photo-viewer-next');let photos=[],index=0,previousFocus=null,start=null;
 function render(){const photo=photos[index];error.hidden=true;image.hidden=false;image.alt=photo.caption||photo.name||'相册照片';image.src=photo.src;q('.photo-viewer-caption').textContent=photo.caption||photo.name||'';q('.photo-viewer-count').textContent=`${index+1} / ${photos.length}`;prev.disabled=next.disabled=photos.length<2;}
 function step(delta){if(!dialog.open||photos.length<2)return;index=(index+delta+photos.length)%photos.length;render()}
 image.onerror=()=>{error.hidden=false;image.hidden=true};image.onload=()=>{error.hidden=true;image.hidden=false};prev.onclick=()=>step(-1);next.onclick=()=>step(1);q('.photo-viewer-close').onclick=()=>dialog.close();
 dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();e.stopPropagation();step(e.key==='ArrowLeft'?-1:1)}});
 dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});
 stage.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'||e.isPrimary===false)return;start={id:e.pointerId,x:e.clientX,y:e.clientY};stage.setPointerCapture(e.pointerId)});
 stage.addEventListener('pointerup',e=>{const origin=start;start=null;if(!origin||origin.id!==e.pointerId)return;const dx=e.clientX-origin.x,dy=e.clientY-origin.y;if(Math.abs(dx)>48&&Math.abs(dx)>Math.abs(dy)*1.3)step(dx<0?1:-1)});stage.addEventListener('pointercancel',()=>{start=null});
 dialog.addEventListener('close',()=>{start=null;photos=[];image.removeAttribute('src');error.hidden=true;previousFocus?.focus()});
 return {close(){if(dialog.open)dialog.close()},open({title,items,slot=0}){const entries=items.filter(p=>p&&typeof p.src==='string'&&p.src);if(!entries.length)return false;photos=entries.map(p=>({...p}));index=Math.max(0,photos.findIndex(p=>p.slot===slot));previousFocus=document.activeElement;q('#photo-viewer-title').textContent=title;render();if(!dialog.open)dialog.showModal();q('.photo-viewer-close').focus();return true},get opened(){return dialog.open}};
}
